    for (int i = 0; i < heights.length; i++) {
      int leftHeight = i - 1 >= 0 ? heights[i - 1] : 0;
      int rightHeight = i + 1 < heights.length ? heights[i + 1] : 0;

      if (heights[i] > leftHeight && heights[i] > rightHeight) {
        count++;
      }
    }

    return count;
  }
}

